# Compaction for a long agent: clear old tool results, then summarise if still big.
def total(msgs):
    return sum(m["tokens"] for m in msgs)

def clear_old_tool_results(msgs, keep_last):
    idx = [i for i, m in enumerate(msgs) if m["role"] == "tool"]
    old = idx[:-keep_last] if keep_last else idx
    for i in old:  # free: swap raw output for a short placeholder
        msgs[i] = {"role": "tool", "text": "[cleared]", "tokens": 8}

def compact(msgs, threshold, keep_recent):
    if total(msgs) <= threshold:
        return msgs
    old, recent = msgs[:-keep_recent], msgs[-keep_recent:]
    # A real agent would ask the model for a summary using a strict template.
    summary = {"role": "user", "text": f"SUMMARY of {len(old)} messages", "tokens": 150}
    return [summary] + recent

msgs = [{"role": "user", "text": "fix bug", "tokens": 50}]
for step in range(6):
    msgs.append({"role": "assistant", "text": f"call {step}", "tokens": 40})
    msgs.append({"role": "tool", "text": "x", "tokens": 3000})
print("before:", total(msgs), "tokens,", len(msgs), "messages")
clear_old_tool_results(msgs, keep_last=2)
print("after clearing:", total(msgs), "tokens")
msgs = compact(msgs, threshold=5000, keep_recent=4)
print("after compaction:", total(msgs), "tokens,", len(msgs), "messages")
print("first message:", msgs[0]["text"])
